// —— In1：LOGIC_H 总线 + 接到排针 ——
const hNodes = [];
const rhi2 = pw('RHI', 2);
if (rhi2) hNodes.push(rhi2);
for (let i = 1; i <= 6; i++) {
  const p = pw(`U${i}`, 1);
  if (p) hNodes.push(p);
}
let hBusEnd = null;
if (logicH && hNodes.length >= 2) {
  const busY = Math.min(...hNodes.map(p => p.y)) - 55;
  const vias = [];
  for (const p of hNodes) {
    const e = { x: p.x, y: busY };
    add(logicH, p, { x: p.x, y: p.y - 35 }, 12, 'F.Cu');
    add(logicH, { x: p.x, y: p.y - 35 }, e, 12, 'F.Cu');
    addVia(logicH, e);
    vias.push(e);
  }
  for (let i = 0; i < vias.length - 1; i++) {
    add(logicH, vias[i], vias[i + 1], 12, 'In1.Cu');
  }
  hBusEnd = vias[vias.length - 1];
}

// —— In2：LOGIC_L 总线 + 接到排针 ——
const lNodes = [];
const rlo1 = pw('RLO', 1);
if (rlo1) lNodes.push(rlo1);
for (const ref of ['U1', 'U2', 'U4', 'U5', 'U6']) {
  const p = pw(ref, 2);
  if (p) lNodes.push(p);
}
let lBusEnd = null;
if (logicL && lNodes.length >= 2) {
  const busY = Math.max(...lNodes.map(p => p.y)) + 55;
  const vias = [];
  for (const p of lNodes) {
    const e = { x: p.x, y: busY };
    add(logicL, p, { x: p.x, y: p.y + 35 }, 12, 'F.Cu');
    add(logicL, { x: p.x, y: p.y + 35 }, e, 12, 'F.Cu');
    addVia(logicL, e);
    vias.push(e);
  }
  for (let i = 0; i < vias.length - 1; i++) {
    add(logicL, vias[i], vias[i + 1], 12, 'In2.Cu');
  }
  lBusEnd = vias[vias.length - 1];
}

// —— B：LOGIC_L → U7 EN/RST ——
const u6l = pw('U6', 2);
const u7en = pw('U7', 14);
const u7rst = pw('U7', 15);
if (logicL && u6l && u7en) {
  routeSig(logicL, u6l, u7en, 'B.Cu', 12, 780);
  if (u7rst) add(logicL, u7en, u7rst, 12, 'F.Cu');
}

const jGnd = pw('J1', 1);
const jVcc = pw('J1', 2);
const jH = pw('J1', 3);
const jL = pw('J1', 4);
const jClk = pw('J1', 5);
const jQ0 = pw('J1', 6);
const jQ1 = pw('J1', 7);
const jQ2 = pw('J1', 8);
if (gnd && jGnd) {
  addVia(gnd, jGnd);
  add(gnd, jGnd, { x: jGnd.x - 35, y: jGnd.y }, 14, 'In1.Cu');
}
if (vcc && jVcc) {
  addVia(vcc, jVcc);
  add(vcc, jVcc, { x: jVcc.x - 35, y: jVcc.y }, 14, 'In2.Cu');
}

// 从总线末端接到排针（同层延续，不再二次扇出交叉）
const busToHdr = (net, busPt, jPad, layer, colX) => {
  if (!net || !busPt || !jPad) return;
  L(net, [busPt, { x: colX, y: busPt.y }, { x: colX, y: jPad.y }], 12, layer);
  addVia(net, { x: colX, y: jPad.y });
  add(net, { x: colX, y: jPad.y }, jPad, 12, 'F.Cu');
};
busToHdr(logicH, hBusEnd, jH, 'In1.Cu', 3280);
busToHdr(logicL, lBusEnd, jL, 'In2.Cu', 3320);

// In2 再走 CLK（与 L 总线不同高度：CLK 上廊）
fanTop(clk, pw('U7', 13), jClk, 'In2.Cu', 50, 3360);

// B：仅 CLK 已用 In2；B 走 Q0（上廊）
fanTop(la[0], pw('U7', 3), jQ0, 'B.Cu', 90, 3400);

// F：Q1/Q2 下廊（互异 runY，不占内层）
const fanFbot = (net, src, jPad, runY) => {
  if (!net || !src || !jPad) return;
  L(net, [
    src,
    { x: src.x, y: runY },
    { x: jPad.x, y: runY },
    jPad
  ], 12, 'F.Cu');
};
fanFbot(la[1], pw('U7', 2), jQ1, 920);
fanFbot(la[2], pw('U7', 4), jQ2, 980);

for (let i = 3; i < 7; i++) {
  const p = pw('U7', qPads[i]);
  if (p && la[i]) {
    const e = { x: p.x - 40, y: p.y };
    add(la[i], p, e, 12, 'F.Cu');
    addVia(la[i], e);
  }
}
